274→func ConvertForMap(anything interface{}) map[string]string {
275→	var m map[string]string
276→	m = make(map[string]string)
277→
278→	r := reflect.ValueOf(anything).Elem()
279→
280→	for i := 0; i < r.NumField(); i++ {
281→		valueField := r.Field(i)
282→		typeField := r.Type().Field(i)
283→		tag := typeField.Tag
284→
285→		if len(valueField.Interface().(string)) > 0 {
286→			m[tag.Get("json")] = valueField.Interface().(string)
287→		}
288→	}
289→
290→	return m
291→}
